package com.andye.warmod.block.entity;import com.andye.warmod.block.*;import com.andye.warmod.item.ModItems;import com.andye.warmod.phalanx.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.UUIDUtil;import net.minecraft.network.protocol.*;import net.minecraft.network.protocol.game.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.Mth;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.storage.*;import net.minecraft.world.phys.*;import org.jspecify.annotations.Nullable;
public final class PhalanxBlockEntity extends BlockEntity implements WorldlyContainer{private static final int[] SLOTS={0,1};private final ItemStack[] ammo={ItemStack.EMPTY,ItemStack.EMPTY};private UUID turretId=UUID.randomUUID();private @Nullable UUID ownerId,currentTarget;private String ownerName="SERVER";private Direction facing=Direction.NORTH;private boolean enabled=true,teardown;private float yaw,pitch,desiredYaw,desiredPitch,bloom,barrelSpin;private long shotSequence;private int shotCooldown,burstShots,recovery;private PhalanxGunStatus status=PhalanxGunStatus.IDLE;public PhalanxBlockEntity(BlockPos p,BlockState s){super(ModBlockEntities.PHALANX_TURRET,p,s);if(s.hasProperty(PhalanxTurretBlock.FACING))facing=s.getValue(PhalanxTurretBlock.FACING);}public void initialize(@Nullable Player owner,Direction facing){turretId=UUID.randomUUID();ownerId=owner==null?null:owner.getUUID();ownerName=owner==null?"SERVER":owner.getGameProfile().name();this.facing=facing;sync();}public UUID turretId(){return turretId;}public boolean enabled(){return enabled;}public void setEnabled(boolean v){enabled=v;sync();}public int rounds(){return ammo[0].getCount()+ammo[1].getCount();}public PhalanxGunStatus status(){return status;}public float yaw(){return yaw;}public float pitch(){return pitch;}public float bloom(){return bloom;}public float barrelSpin(){return barrelSpin;}public @Nullable UUID currentTarget(){return currentTarget;}public boolean teardown(){return teardown;}public void setTeardown(boolean v){teardown=v;}public static void serverTick(Level l,BlockPos p,BlockState s,PhalanxBlockEntity be){if(!(l instanceof ServerLevel level))return;be.tick(level);}private void tick(ServerLevel level){if(!PhalanxStructure.complete(level,worldPosition)||!enabled){status=PhalanxGunStatus.IDLE;cool();return;}if(rounds()==0){status=PhalanxGunStatus.OUT_OF_AMMO;currentTarget=null;cool();return;}Vec3 centre=Vec3.atCenterOf(worldPosition),muzzle=centre.add(0,1.42,0);var selected=PhalanxTargetSelector.select(centre,muzzle,PhalanxTargetService.snapshot(level));if(selected.isEmpty()){status=PhalanxGunStatus.IDLE;currentTarget=null;cool();return;}var target=selected.get();currentTarget=target.targetId();Vec3 delta=target.position().subtract(muzzle);desiredYaw=(float)Math.toDegrees(Math.atan2(delta.z,delta.x))-90;desiredPitch=(float)-Math.toDegrees(Math.atan2(delta.y,delta.horizontalDistance()));yaw=approach(yaw,desiredYaw,12);pitch=approach(pitch,desiredPitch,8);double elevation=-pitch;if(elevation>PhalanxConstants.MAX_ELEVATION_DEGREES||elevation<PhalanxConstants.MIN_ELEVATION_DEGREES){status=PhalanxGunStatus.TARGET_OUT_OF_ARC;cool();return;}status=PhalanxGunStatus.TRACKING;barrelSpin=Math.min(1,barrelSpin+.12F);if(recovery>0){recovery--;status=PhalanxGunStatus.RELOADING;return;}if(shotCooldown>0){shotCooldown--;return;}var solution=PhalanxLeadSolver.solve(muzzle,target.position(),target.velocity());if(solution.isEmpty()||angleError(solution.get().direction())>6||barrelSpin<.72F)return;double spread=Math.min(PhalanxConstants.MAX_SPREAD_DEGREES,PhalanxConstants.BASE_SPREAD_DEGREES+bloom);Vec3 direction=PhalanxLeadSolver.spread(solution.get().direction(),turretId,shotSequence,level.getGameTime(),spread);if(!PhalanxBulletManager.fire(level,this,target.targetId(),muzzle,direction.scale(PhalanxConstants.BULLET_SPEED_BLOCKS_PER_TICK),turretId.getMostSignificantBits()^shotSequence))return;consumeRound();shotSequence++;burstShots++;shotCooldown=PhalanxConstants.SHOT_INTERVAL_TICKS;status=PhalanxGunStatus.FIRING;bloom=(float)Math.min(PhalanxConstants.MAX_SPREAD_DEGREES-PhalanxConstants.BASE_SPREAD_DEGREES,bloom+PhalanxConstants.BLOOM_PER_SHOT_DEGREES);if(burstShots>=PhalanxConstants.BURST_SIZE){burstShots=0;recovery=PhalanxConstants.BURST_RECOVERY_TICKS;}sync();}private double angleError(Vec3 direction){Vec3 aim=new Vec3(-Mth.sin(yaw*Mth.DEG_TO_RAD)*Mth.cos(pitch*Mth.DEG_TO_RAD),-Mth.sin(pitch*Mth.DEG_TO_RAD),Mth.cos(yaw*Mth.DEG_TO_RAD)*Mth.cos(pitch*Mth.DEG_TO_RAD));return Math.toDegrees(Math.acos(Mth.clamp(aim.normalize().dot(direction),-1,1)));}private static float approach(float current,float target,float max){return current+Mth.clamp(Mth.wrapDegrees(target-current),-max,max);}private void cool(){bloom=Math.max(0,bloom-(float)PhalanxConstants.BLOOM_RECOVERY_DEGREES_PER_TICK);barrelSpin=Math.max(0,barrelSpin-.08F);}private void consumeRound(){for(int i=0;i<2;i++)if(!ammo[i].isEmpty()){ammo[i].shrink(1);if(ammo[i].isEmpty())ammo[i]=ItemStack.EMPTY;setChanged();return;}}private void sync(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}@Override public int getContainerSize(){return 2;}@Override public boolean isEmpty(){return rounds()==0;}@Override public ItemStack getItem(int slot){return slot>=0&&slot<2?ammo[slot]:ItemStack.EMPTY;}@Override public ItemStack removeItem(int slot,int count){if(slot<0||slot>1||count<=0)return ItemStack.EMPTY;ItemStack result=ammo[slot].split(count);if(ammo[slot].isEmpty())ammo[slot]=ItemStack.EMPTY;sync();return result;}@Override public ItemStack removeItemNoUpdate(int slot){if(slot<0||slot>1)return ItemStack.EMPTY;ItemStack result=ammo[slot];ammo[slot]=ItemStack.EMPTY;return result;}@Override public void setItem(int slot,ItemStack stack){if(slot<0||slot>1)return;ammo[slot]=stack.is(ModItems.ANTI_AIR_GUN_AMMO)?stack.copyWithCount(Math.min(64,stack.getCount())):ItemStack.EMPTY;sync();}@Override public int getMaxStackSize(){return 64;}@Override public boolean stillValid(Player p){return level==p.level()&&p.distanceToSqr(Vec3.atCenterOf(worldPosition))<=64;}@Override public boolean canPlaceItem(int slot,ItemStack stack){return slot>=0&&slot<2&&stack.is(ModItems.ANTI_AIR_GUN_AMMO);}@Override public void clearContent(){ammo[0]=ammo[1]=ItemStack.EMPTY;sync();}@Override public int[] getSlotsForFace(Direction d){return SLOTS;}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,@Nullable Direction d){return canPlaceItem(slot,stack);}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction d){return slot>=0&&slot<2;}@Override protected void saveAdditional(ValueOutput o){super.saveAdditional(o);o.store("turret_id",UUIDUtil.CODEC,turretId);o.storeNullable("owner_id",UUIDUtil.CODEC,ownerId);o.putString("owner_name",ownerName);o.putString("facing",facing.getSerializedName());o.putBoolean("enabled",enabled);o.putFloat("yaw",yaw);o.putFloat("pitch",pitch);o.putFloat("bloom",bloom);o.putLong("shot_sequence",shotSequence);o.store("ammo_0",ItemStack.CODEC,ammo[0]);o.store("ammo_1",ItemStack.CODEC,ammo[1]);}@Override protected void loadAdditional(ValueInput i){super.loadAdditional(i);turretId=i.read("turret_id",UUIDUtil.CODEC).orElseGet(UUID::randomUUID);ownerId=i.read("owner_id",UUIDUtil.CODEC).orElse(null);ownerName=i.getStringOr("owner_name","SERVER");facing=Direction.byName(i.getStringOr("facing","north"));if(facing==null)facing=Direction.NORTH;enabled=i.getBooleanOr("enabled",true);yaw=i.getFloatOr("yaw",0);pitch=i.getFloatOr("pitch",0);bloom=i.getFloatOr("bloom",0);shotSequence=i.getLongOr("shot_sequence",0);ammo[0]=i.read("ammo_0",ItemStack.CODEC).orElse(ItemStack.EMPTY);ammo[1]=i.read("ammo_1",ItemStack.CODEC).orElse(ItemStack.EMPTY);}@Override public @Nullable Packet<ClientGamePacketListener> getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public net.minecraft.nbt.CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider r){return saveCustomOnly(r);}}
